// lib/services/youtube_service.dart
import 'package:youtube_explode_dart/youtube_explode_dart.dart';
import '../models/subtitle_segment.dart';

class YoutubeService {
  final YoutubeExplode _yt = YoutubeExplode();

  /// Extracts video title and transcript segments from a YouTube URL.
  /// Prioritises manual English captions, falls back to auto-generated.
  Future<({String title, String videoId, List<SubtitleSegment> segments})>
      extractTranscript(String url) async {
    final videoId = _parseVideoId(url);
    if (videoId == null) {
      throw Exception(
          'Could not parse a valid YouTube video ID from the URL.\n'
          'Make sure you are sharing a standard youtube.com or youtu.be link.');
    }

    // Fetch video metadata for the title.
    final video = await _yt.videos.get(videoId);
    final title = video.title;

    // Fetch closed captions manifest.
    final manifest =
        await _yt.videos.closedCaptions.getManifest(videoId);

    if (manifest.tracks.isEmpty) {
      throw Exception(
          'This video has no closed captions available.\n'
          'The video creator has not provided any captions, '
          'and auto-generated captions are unavailable.');
    }

    // Priority 1: manual English. Priority 2: any manual. Priority 3: auto en.
    // Priority 4: first available track.
    ClosedCaptionTrackInfo? trackInfo;

    final manualEn = manifest.tracks.where(
      (t) => !t.isAutoGenerated && t.language.code.startsWith('en'),
    );
    if (manualEn.isNotEmpty) {
      trackInfo = manualEn.first;
    }

    if (trackInfo == null) {
      final manualAny =
          manifest.tracks.where((t) => !t.isAutoGenerated);
      if (manualAny.isNotEmpty) {
        trackInfo = manualAny.first;
      }
    }

    if (trackInfo == null) {
      final autoEn = manifest.tracks.where(
        (t) => t.isAutoGenerated && t.language.code.startsWith('en'),
      );
      if (autoEn.isNotEmpty) {
        trackInfo = autoEn.first;
      }
    }

    trackInfo ??= manifest.tracks.first;

    // Download and parse the actual caption track.
    final track = await _yt.videos.closedCaptions.get(trackInfo);

    final List<SubtitleSegment> segments = [];
    for (int i = 0; i < track.captions.length; i++) {
      final c = track.captions[i];
      final text = c.text.trim();
      if (text.isEmpty) continue;
      segments.add(SubtitleSegment(
        index: segments.length,
        start: c.offset,
        duration: c.duration,
        originalText: text,
      ));
    }

    if (segments.isEmpty) {
      throw Exception(
          'The caption track was downloaded but contained no text segments.');
    }

    return (title: title, videoId: videoId, segments: segments);
  }

  /// Parses a YouTube video ID from various URL formats.
  String? _parseVideoId(String url) {
    final cleaned = url.trim();

    // Try youtube_explode's built-in parser first.
    try {
      final id = VideoId.parseVideoId(cleaned);
      if (id != null) return id;
    } catch (_) {}

    // Manual fallback patterns.
    final patterns = [
      RegExp(r'(?:v=|/v/|youtu\.be/|/embed/|/shorts/)([A-Za-z0-9_-]{11})'),
      RegExp(r'^([A-Za-z0-9_-]{11})$'),
    ];

    for (final pattern in patterns) {
      final match = pattern.firstMatch(cleaned);
      if (match != null) return match.group(1);
    }
    return null;
  }

  void dispose() => _yt.close();
}
